import{_ as e}from"./chunks/image3.B8UTGdq_.js";import{_ as a,o as i,c as o,ah as n}from"./chunks/framework.inWAIpeo.js";const s="/projects/PuppyPi/en/latest/assets/image1.C_0XAjKS.webp",r="/projects/PuppyPi/en/latest/assets/image2.CfMYgUuL.webp",l="/projects/PuppyPi/en/latest/assets/image3.DocQfqrE.webp",p="/projects/PuppyPi/en/latest/assets/image4.BTs4jmXq.webp",h="/projects/PuppyPi/en/latest/assets/image5.B-4Sox7m.webp",c="/projects/PuppyPi/en/latest/assets/image6.BaWWs3XP.webp",g="/projects/PuppyPi/en/latest/assets/image7.CJtybOsO.webp",d="/projects/PuppyPi/en/latest/assets/image8.DhJuuH_N.webp",m="/projects/PuppyPi/en/latest/assets/image9.IIJ0cJ1h.webp",u="/projects/PuppyPi/en/latest/assets/image10.Kh60tXdI.webp",b="/projects/PuppyPi/en/latest/assets/image11.CfW1wc5k.webp",v="/projects/PuppyPi/en/latest/assets/image12.bxX1tLuz.webp",y="/projects/PuppyPi/en/latest/assets/image13.CTgIRjcv.webp",f="/projects/PuppyPi/en/latest/assets/image14.Dkeb1san.webp",w="/projects/PuppyPi/en/latest/assets/image2.B8mhUNwY.webp",k="/projects/PuppyPi/en/latest/assets/image3.Cu369rB1.webp",_="/projects/PuppyPi/en/latest/assets/image4.BCAqqIhI.webp",P="/projects/PuppyPi/en/latest/assets/image5.809BlLAw.webp",z="/projects/PuppyPi/en/latest/assets/image6.CrFz5FLD.webp",A="/projects/PuppyPi/en/latest/assets/image7.BVGDPbxQ.webp",C="/projects/PuppyPi/en/latest/assets/image8.D9lCj8Nu.webp",q="/projects/PuppyPi/en/latest/assets/image9.CTBlw890.webp",I="/projects/PuppyPi/en/latest/assets/image5.BirY44eG.webp",M="/projects/PuppyPi/en/latest/assets/image11.CwwxHjLl.webp",T="/projects/PuppyPi/en/latest/assets/image13.mYCnkx6w.webp",F="/projects/PuppyPi/en/latest/assets/image15.C6By7r7j.webp",L="/projects/PuppyPi/en/latest/assets/image16.C73HN5Sv.webp",x="data:image/png;base64,",S="/projects/PuppyPi/en/latest/assets/image19.CBAm-Oai.webp",j="/projects/PuppyPi/en/latest/assets/image24.DhcJ4Yx1.webp",N="/projects/PuppyPi/en/latest/assets/image29.iSV6P6lk.webp",R="/projects/PuppyPi/en/latest/assets/image30.DH2EJTn2.webp",B="/projects/PuppyPi/en/latest/assets/image31.CtW9uSuk.webp",O="/projects/PuppyPi/en/latest/assets/image32.Bmwoz8fT.webp",D="/projects/PuppyPi/en/latest/assets/image33.e5-ZT9Nh.webp",G="/projects/PuppyPi/en/latest/assets/image34.B8yPcFP5.webp",E="/projects/PuppyPi/en/latest/assets/image35.opQWolIB.webp",W="/projects/PuppyPi/en/latest/assets/image37.CYQZMOQo.webp",Y="/projects/PuppyPi/en/latest/assets/image38.BpZnBpwl.webp",Z="/projects/PuppyPi/en/latest/assets/image39.b2f3pTb9.webp",V="/projects/PuppyPi/en/latest/assets/image6.ChG0nUhq.webp",H="/projects/PuppyPi/en/latest/assets/image7.BBx5vmJb.webp",U="/projects/PuppyPi/en/latest/assets/image22.B-F7-NOc.webp",ot=JSON.parse('{"title":"16. ROS1-Autonomous Navigation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/16.ROS1_Autonomous_Navigation.md","filePath":"docs/16.ROS1_Autonomous_Navigation.md"}'),J={name:"docs/16.ROS1_Autonomous_Navigation.md"};function Q(X,t,K,$,tt,et){return i(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="_16-ros1-autonomous-navigation" tabindex="-1">16. ROS1-Autonomous Navigation <a class="header-anchor" href="#_16-ros1-autonomous-navigation" aria-label="Permalink to &quot;16. ROS1-Autonomous Navigation&quot;">​</a></h1><h2 id="_16-1-ros-robot-autonomous-navigation-principle" tabindex="-1">16.1 ROS Robot Autonomous Navigation Principle <a class="header-anchor" href="#_16-1-ros-robot-autonomous-navigation-principle" aria-label="Permalink to &quot;16.1 ROS Robot Autonomous Navigation Principle&quot;">​</a></h2><h3 id="_16-1-1-autonomous-navigation-introduction" tabindex="-1">16.1.1 Autonomous Navigation Introduction <a class="header-anchor" href="#_16-1-1-autonomous-navigation-introduction" aria-label="Permalink to &quot;16.1.1 Autonomous Navigation Introduction&quot;">​</a></h3><p>The so-called autonomous navigation refers to the ability of the robot to move from point A to point B on its own. To achieve this functionality, the robot requires fixed components: global map, self-localization, path planning, motion control, and environmental perception. It is through these components that the subsequent autonomous navigation functionality can be realized. You can refer to the following image for more details:</p><img loading="lazy" height="319" width="780" class="common_img" src="'+s+'"><h3 id="_16-1-2-autonomous-navigation-principle" tabindex="-1">16.1.2 Autonomous Navigation Principle <a class="header-anchor" href="#_16-1-2-autonomous-navigation-principle" aria-label="Permalink to &quot;16.1.2 Autonomous Navigation Principle&quot;">​</a></h3><p>The five essential components mentioned earlier correspond to different feature packs inside a robot.</p><p><strong>Global map:</strong> The robot builds a global map of the environment through the process of Simultaneous Localization and Mapping (SLAM) for navigation. To learn more about SLAM, please refer to the file &quot;<a href="./15.ROS1_SLAM_Mapping_Course.html#slam-mapping-principle"><strong>15. ROS1-SLAM Mapping Course -&gt; 15.1 SLAM Mapping Principle</strong></a>&quot;.</p><p><strong>Self-localization:</strong> The robot usually utilizes algorithms to calculate its current location. Two commonly used algorithms include using odometry to calculate the robot&#39;s position relative to a known origin, and using Lidar to sense the environment and compare the received information with the feature points of the map to determine the robot&#39;s location.</p><p><strong>Path planning:</strong> The robot plans its path by utilizing both the global map and local map. The robot builds a global map through SLAM mapping and obtains a local map through real-time LIDAR scanning.</p><p><strong>Motion control:</strong> The robot&#39;s movement can be controlled by sending messages to it.</p><p><strong>Environment perception:</strong> The robot perceives its surroundings through lidar, which is helpful for SLAM mapping, self-localization, and navigation.</p><h2 id="_16-2-adaptive-monte-carlo-localization" tabindex="-1">16.2 Adaptive Monte Carlo Localization <a class="header-anchor" href="#_16-2-adaptive-monte-carlo-localization" aria-label="Permalink to &quot;16.2 Adaptive Monte Carlo Localization&quot;">​</a></h2><h3 id="_16-2-1-amcl-localization" tabindex="-1">16.2.1 AMCL Localization <a class="header-anchor" href="#_16-2-1-amcl-localization" aria-label="Permalink to &quot;16.2.1 AMCL Localization&quot;">​</a></h3><p>Localization involves estimating the robot&#39;s position in the global map. While SLAM includes localization algorithms, SLAM&#39;s localization is used to construct the global map and is part of the pre-navigation phase. Current localization is used during navigation when the robot needs to move along a predefined route. Through localization, we can assess whether the robot&#39;s actual trajectory matches the expected one. The ROS navigation function package, ros-navigation, provides the AMCL localization system for implementing robot localization during navigation. AMCL (Adaptive Monte Carlo Localization) is a probabilistic localization system designed for 2D mobile robots. It implements the adaptive Monte Carlo localization method, which uses a particle filter to estimate the robot&#39;s position based on the existing map. Localization resolves the association issue between robots and obstacles, as path planning essentially involves decision-making based on obstacles around the robot. In theory, as long as the robot&#39;s global positioning is known and real-time obstacle avoidance is achieved through sensor scan information from devices like laser radar, navigation tasks can be accomplished. However, the real-time accuracy of global positioning is generally not high, provided by local positioning methods such as odometers and IMUs, which ensure the real-time accuracy of the robot&#39;s motion trajectory with the IMU. The amcl node in the navigation function package provides global positioning by publishing map_odom. Global positioning by amcl is not mandatory; users can replace amcl global positioning with other methods that can provide map_odom, such as using SLAM, UWB, or QR code positioning. Global positioning and local positioning have established a dynamic set of TF coordinates: map_odom, base_footprint, and the static TF coordinates between various sensors in the robot are provided through the robot&#39;s URDF model. This part of the TF relationship resolves the association problem between the robot and obstacles. For example, if a laser radar detects an obstacle 3 meters ahead, using the TF coordinates between the laser radar and the robot&#39;s chassis, the transformation from base_link to laser_link can be obtained, which reveals the relationship between the obstacle and the robot&#39;s chassis.</p><p>AMCL Learning Wiki：<a href="http://wiki.ros.org/amcl" target="_blank" rel="noreferrer">http://wiki.ros.org/amcl</a></p><p>AMCL Package Link：<a href="https://github.com/ros-planning/navigation/tree/melodic-devel/amcl" target="_blank" rel="noreferrer">https://github.com/ros-planning/navigation/tree/melodic-devel/amcl</a></p><h3 id="_16-2-2-particle-filter" tabindex="-1">16.2.2 Particle Filter <a class="header-anchor" href="#_16-2-2-particle-filter" aria-label="Permalink to &quot;16.2.2 Particle Filter&quot;">​</a></h3><p>Monte Carlo Localization (MCL) involves a particle update process for a one-dimensional robot. Initially, a group of particles is randomly generated, each representing possible states of the robot, including position, direction, or other estimated state variables. Each particle has a weight, indicating its similarity to the actual system state. Next, the state of each particle for the next time step is predicted based on the expected behavior of the real system. Subsequently, the weights of particles are updated based on measurements, with particles that match the measurement being assigned higher weights. Afterward, resampling is performed, discarding highly unlikely particles and replacing them with more probable ones. Finally, the weighted mean and covariance of the particle set are calculated to obtain the estimated state.</p><img loading="lazy" height="295" width="296" class="common_img" src="'+r+'"><img loading="lazy" height="336" width="348" class="common_img" src="'+l+'"><p>Monte Carlo methods vary, but tend to follow a specific pattern:</p><p>(1) Define the domain of possible inputs.</p><p>(2) Randomly generate inputs from the probability distribution over the domain.</p><p>(3) Perform deterministic computations on the inputs.</p><p>(4) Summarize the results.</p><p>Two important considerations are:</p><p>(1) If these points are not uniformly distributed, the approximation may be poor.</p><p>(2) This process requires many points. If only a few points are randomly placed within the entire square, the approximation is usually poor. On average, increasing the number of points improves the accuracy of the approximation.</p><p>The Monte Carlo particle filtering algorithm has wide-ranging applications in various fields such as physics, engineering, climatology, and computational biology.</p><h3 id="_16-2-3-adaptive-monte-carlo-localization" tabindex="-1">16.2.3 Adaptive Monte Carlo Localization <a class="header-anchor" href="#_16-2-3-adaptive-monte-carlo-localization" aria-label="Permalink to &quot;16.2.3 Adaptive Monte Carlo Localization&quot;">​</a></h3><p>AMCL can be regarded as an improved version of the Monte Carlo localization algorithm. It reduces execution time and enhances real-time performance by employing a small number of samples in the Monte Carlo localization algorithm. It implements an adaptive or KLD-sampling Monte Carlo localization method, which utilizes particle filtering to track a robot&#39;s pose with respect to a known map. The Adaptive Monte Carlo Localization (AMCL) node primarily utilizes laser scans and laser map data to propagate messages and compute pose estimates. In the implementation process, it first initializes the particle filter of the Adaptive Monte Carlo Localization algorithm based on various initialization parameters provided by the ROS system. If the initial pose is not specified, the AMCL algorithm assumes that the robot starts running from the origin of the coordinate system, which can lead to relatively complex calculations. Therefore, it is recommended to set the initial pose using the &quot;<strong>2D Pose Estimate</strong>&quot; button in rviz. For more information about Adaptive Monte Carlo Localization, you can also refer to the wiki page at the following link: <a href="https://github.com/ros-planning/navigation" target="_blank" rel="noreferrer">https://github.com/ros-planning/navigation</a></p><h3 id="_16-2-4-costmap" tabindex="-1">16.2.4 Costmap <a class="header-anchor" href="#_16-2-4-costmap" aria-label="Permalink to &quot;16.2.4 Costmap&quot;">​</a></h3><p>Whether generated by a laser scanner or depth camera, 2D or 3D SLAM maps cannot be directly used for actual navigation. They must be converted into costmaps. In ROS, costmaps are typically represented in grid format. Each grid cell in the grid map occupies one byte, which is eight bits, capable of storing data from 0 to 255. This means that each cell cost (the value of the grid) ranges from 0 to 255, with only three scenarios considered: Occupied (presence of obstacles), Free (open space without obstacles), and Unknown Space (areas where information is lacking).</p><p>Before introducing costmap_2d, let&#39;s first talk about the Bresenham algorithm. The Bresenham Line Algorithm is used to draw a straight line determined by two points. It calculates the closest points on an n-dimensional grid to the line segment. This algorithm only requires relatively fast integer addition, subtraction, and bit shifting operations, making it commonly used for drawing lines in computer graphics. It is one of the earliest developed algorithms in computer graphics.</p><img loading="lazy" height="325" width="488" class="common_img" src="'+p+'"><p>Scan through the center of pixels in each row and column to construct a set of virtual grid lines as shown in the diagram above. Calculate the intersections of the line with each vertical grid line in the order from the starting point to the endpoint of the line, and then determine the pixel closest to this intersection point within the column of pixels based on the sign of the error term. Algorithm Core Idea: Assume: k = dy/dx. Because the starting point of the line is at the center of a pixel, the initial value of the error term d is set to d0 = 0. As X increases by 1, the value of d increases correspondingly by the slope value k of the line, that is, d = d + k. Once d ≥ 1, subtract 1 from it to ensure that d remains between 0 and 1. When d ≥ 0.5, the pixel closest to the current pixel is the one at the upper right corner (x+1, y+1), and when d &lt; 0.5, it is closer to the right pixel (x+1, y). For convenience in computation, let e = d - 0.5, where the initial value of e is -0.5, and the increment is k. When e ≥ 0, take the pixel at the upper right corner of the current pixel (xi, yi) as (x+1, y+1), and when e &lt; 0, it is closer to the right pixel (x+1, y). To avoid division, integers can be used. Since only the sign of the error term is used in the algorithm, it can be replaced as follows: e1 = 2<em>e</em>dx.</p><img loading="lazy" height="748" width="832" class="common_img" src="'+h+'"><p>The Costmap2D class maintains the cost values for each grid. The Layer class is a virtual base class that provides a unified interface for various plugin costmap layers. The most important interface functions include: The &quot;<strong>initialize</strong>&quot; function, which calls the &quot;<strong>onInitialize</strong>&quot; function, initializes each costmap layer separately. The &quot;<strong>matchSize</strong>&quot; function, used in both the StaticLayer and ObstacleLayer classes, calls the &quot;<strong>matchSize</strong>&quot; function of the CostmapLayer class. This function initializes the size, resolution, origin, and default cost of each costmap layer, ensuring consistency with the layered_costmap. For the InflationLayer class, it calculates a cost table that varies with distance based on the inflation radius. This allows for querying the cost values of inflated grid cells based on distance. Additionally, the &quot;<strong>seen_</strong>&quot; array is defined to mark whether a grid cell has been traversed. For the VoxelLayer class, it initializes the size of voxel grids.</p><p>The &quot;<strong>updateBounds</strong>&quot; function adjusts the size range that the current costmap layer needs to update. For the StaticLayer class, it sets the update range of the costmap to the size of the static map (note: the static layer is generally used only in the global costmap). For the ObstacleLayer class, it traverses the sensor data in &quot;<strong>clearing_observations</strong>&quot; to determine the boundaries of the obstacles.</p><p>The &quot;<strong>initialize</strong>&quot; and &quot;<strong>matchSize</strong>&quot; functions are executed only once. The &quot;<strong>updateBounds</strong>&quot; and &quot;<strong>updateCosts</strong>&quot; functions are executed periodically, with their execution frequency determined by <code>map_update_frequency</code>.</p><p>The CostmapLayer class inherits from both the Layer class and the Costmap2D class and provides several methods for updating cost values. The StaticLayer and ObstacleLayer classes need to store the cost values of the instantiated costmap layer, so they both inherit from the CostmapLayer class. The StaticLayer class updates its costmap using static grid map data, while the ObstacleLayer class updates its costmap using sensor data. The VoxelLayer class, compared to the ObstacleLayer class, additionally considers data along the z-axis. The main difference in their effects is reflected in the clearing of obstacles: one performs clearing in a two-dimensional plane, while the other handles it in three dimensions.</p><img loading="lazy" height="434" width="651" class="common_img" src="'+c+'"><p>The costmap is highly flexible in measuring obstacles, allowing for the creation of specific layers as needed, where obstacle information can be maintained. If the robot is equipped only with a laser scanner, an Obstacles layer should be created to maintain the obstacle information detected by the laser scanner. If the robot also has ultrasonic sensors, a new Sonar layer should be created to maintain the obstacle information detected by the sonar sensors. Each layer can have its own rules for updating obstacles, such as adding obstacles, removing obstacles, and updating the confidence of obstacle points, which greatly enhances the scalability of the navigation system.</p><p><strong>For more information, you can refer to:</strong></p><p>ROS navigation wiki: <a href="http://wiki.ros.org/navigation" target="_blank" rel="noreferrer">http://wiki.ros.org/navigation</a></p><p>ROS move_base wiki: <a href="http://wiki.ros.org/move_base" target="_blank" rel="noreferrer">http://wiki.ros.org/move_base</a></p><h3 id="_16-2-5-global-path-planning" tabindex="-1">16.2.5 Global Path Planning <a class="header-anchor" href="#_16-2-5-global-path-planning" aria-label="Permalink to &quot;16.2.5 Global Path Planning&quot;">​</a></h3><p>Preface: Based on the mobile robot&#39;s understanding of the environment, the nature of the environment, and the algorithms used, path planning can be divided into environment-based path planning algorithms, map-based path planning algorithms, and completeness-based path planning algorithms.</p><img loading="lazy" height="338" width="665" class="common_img" src="'+g+'"><p>Commonly used path planning algorithms in robot autonomous navigation include Dijkstra, A*, D*, PRM, RRT, genetic algorithms, ant colony algorithms, fuzzy algorithms, and others.</p><p>Dijkstra and A* are both graph-based path search algorithms commonly used in robotics. The navigation package integrates global path planning plugins such as navfn, global planner, and carrot planner. Users can choose one of them to load into move_base for navigation. Alternatively, third-party global path planning plugins like SBPL_Lattice_Planner and srl_global_planner can be selected and loaded into move_base. Additionally, users have the option to develop their own global path planning plugins according to the nav_core interface specifications.</p><img loading="lazy" height="360" width="932" class="common_img" src="'+d+'"><p>Robot navigation utilizes path planning to enable it to reach its destination. The navigation planning layer can be divided into global path planning layer, local path planning layer, behavior execution layer, and so on. <strong>(1) Global Path Planning Layer:</strong> Based on the given target, it accepts costmap information to generate a global costmap, plans the global path from the starting point to the target location, and serves as a reference for local path planning. <strong>(2) Local Path Planning Layer:</strong> As the local planning part of the navigation system, it accepts the generated local costmap information based on the costmap, and performs local path planning based on nearby obstacle information. <strong>(3) Behavior Execution Layer:</strong> Combining the commands sent from the upper layers and the path planning results, it determines the current behavior of the mobile robot. As a key focus area in mobile robot research, the quality of path planning algorithms largely determines the efficiency of the robot&#39;s operations.</p><ul><li><strong>Dijkstra algorithm</strong></li></ul><p>The Dijkstra algorithm is a typical shortest path algorithm. It is a single-source shortest path algorithm characterized by expanding outward from the starting point in a breadth-first search manner until reaching the destination. It is a breadth-first algorithm that considers edge weights and is one of the most commonly used algorithms in global path planning problems.</p><p>Below is an illustration of the Dijkstra algorithm.</p><p>(1) At the beginning, we initialize dis[start] to 0, and the rest of the points are initialized to inf.</p><img loading="lazy" height="598" width="710" class="common_img" src="'+m+'"><p>(2) In the first loop, we find the point 1 with the minimum dis value. We then mark 1 as visited and update the dis values of all adjacent blue points. Specifically, we set dis[2] = 2, dis[3] = 4, and dis[4] = 7.</p><img loading="lazy" height="577" width="726" class="common_img" src="'+u+'"><p>(3) In the second loop, we find the point 2 with the minimum dis value. We then mark 2 as visited and update the dis values of all adjacent blue points. Specifically, we set dis[3] = 3 and dis[5] = 4.</p><img loading="lazy" height="575" width="716" class="common_img" src="'+b+'"><p>(4) In the third loop, we find the point 3 with the minimum dis value. We then mark 3 as visited and update the dis value of the adjacent blue point. Specifically, we set dis[4] = 4.</p><img loading="lazy" height="578" width="718" class="common_img" src="'+v+'"><p>(5) In the following two loops, we mark points 4 and 5 as visited, respectively, and the algorithm ends. We have found the shortest paths from the start node to all other nodes.</p><p>For information and usage instructions on the Dijkstra algorithm, you can visit the following link: <a href="http://wiki.ros.org/navfn" target="_blank" rel="noreferrer">http://wiki.ros.org/navfn</a></p><ul><li><strong>A* algorithm</strong></li></ul><p>A* algorithm is a modification of the Dijkstra algorithm, optimized for a single destination. While Dijkstra&#39;s algorithm can find paths to all locations, A* searches for the closest path to one or several locations. It prioritizes paths that appear to be closer to the goal.</p><p>A* algorithm&#39;s formula is: F = G + H, where G is the cost of moving from the starting point to the specified grid, and H is the estimated cost of moving from the specified grid to the endpoint. There are two common methods to calculate the H value:</p><p>(1) Calculate the distance of horizontal and vertical movement; diagonal movement is not considered (Manhattan distance).</p><img loading="lazy" height="262" width="350" src="'+y+'" class="common_img"><p>(2) Calculate the distance of horizontal and vertical movement, allowing diagonal movement (Euclidean distance).</p><img loading="lazy" height="211" width="301" src="'+f+'" class="common_img"><p>For information and instructions on using the A* algorithm, please refer to the video tutorials or visit the following link on the wiki: <a href="http://wiki.ros.org/global" target="_blank" rel="noreferrer">http://wiki.ros.org/global</a> planner</p><p>And redblobgames website: <em><a href="https://www.redblobgames.com/pathfinding/a-star/introduction.html#graphs" target="_blank" rel="noreferrer">https://www.redblobgames.com/pathfinding/a-star/introduction.html#graphs</a></em>*</p><h2 id="_16-3-single-point-and-multi-points-navigation-and-obstacle-avoidance" tabindex="-1">16.3 Single-point and Multi-points Navigation and Obstacle Avoidance <a class="header-anchor" href="#_16-3-single-point-and-multi-points-navigation-and-obstacle-avoidance" aria-label="Permalink to &quot;16.3 Single-point and Multi-points Navigation and Obstacle Avoidance&quot;">​</a></h2><h3 id="_16-3-1-virtual-machine-installation-and-configuration" tabindex="-1">16.3.1 Virtual Machine Installation and Configuration <a class="header-anchor" href="#_16-3-1-virtual-machine-installation-and-configuration" aria-label="Permalink to &quot;16.3.1 Virtual Machine Installation and Configuration&quot;">​</a></h3><p>Due to the limited computing power of Raspberry Pi, virtual machine will take over part of mapping work. Mapping and navigation both require communication between the virtual machine and PuppyPi. We need to modify the configurations of both to enable this communication</p><ul><li><strong>Open and Import Virtual Machine</strong></li></ul><p>(1) Unzip the virtual machine files in any non-Chinese directory within the same directory.</p><img loading="lazy" height="147" width="796" class="common_img" src="'+w+'"><p>(2) Open a virtual machine.</p><img loading="lazy" height="171" width="534" class="common_img" src="'+k+'"><p>(3) Select the folder where virtual machine file is extracted, then open it.</p><img loading="lazy" height="437" width="796" class="common_img" src="'+_+'"><p>(4) Enter the name and set the storage path for virtual machine. Then click &quot;<strong>Import</strong>&quot;.</p><img loading="lazy" height="230" width="345" class="common_img" src="'+P+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>after the first importing, you can directly select the storage path for the previous virtual machine, and open it without importing it again.</p></section><ul><li><strong>Network Configuration of Virtual Machine</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>if you are using desktop computer, please prepare a wireless LAN adapter or USB wireless adapter.</p></section><p>(1) Firstly, start PuppyPi, and join the WiFi created by PuppyPi on computer.</p><img loading="lazy" height="218" width="356" class="common_img" src="'+z+'"><p>(2) Return to the virtual machine interface, and click <strong>&quot;edit-&gt;virtual machine editor&quot;</strong>.</p><img loading="lazy" height="198" width="356" class="common_img" src="'+A+'"><p>(3) Select the wireless network card to be bridged. Then click OK.</p><img loading="lazy" height="285" width="600" class="common_img" src="'+C+'"><img loading="lazy" height="273" width="603" class="common_img" src="'+q+'"><p>(4) Open virtual machine, and power on virtual machine.</p><img loading="lazy" height="309" width="297" class="common_img" src="'+I+'"><p>(5) When entering the system desktop, right click the desktop and select <strong>&quot;open in terminal&quot;</strong>.</p><img loading="lazy" height="513" width="1266" class="common_img" src="'+M+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The input command should be case sensitive and the keywords can be complemented by &quot;<strong>Tab</strong>&quot; key.</p></section><p>(6) Input command <strong>&quot;ifconfig&quot;</strong> and press Enter to check the IP of virtual machine. And the IP is as the red frame shown.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ifconfig</span></span></code></pre></div><img loading="lazy" height="337" width="727" class="common_img" src="'+T+'"><p>(7) Right click the system desktop, and open a new command line terminal. Then input command <strong>&quot;sudo nano /etc/hosts&quot;</strong> and press Enter to configure the network.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/hosts</span></span></code></pre></div><p>(8) Modify the IP in the second and the third lines as the IP of virtual machine and Raspberry Pi you got in the previous step. And the fixed IP of Raspberry Pi under direct connection mode is &quot;<strong>192.168.149.1</strong>&quot;.</p><img loading="lazy" height="174" width="725" class="common_img" src="'+F+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>When modifying the IP, please ensure the indent is consistent.</p></section><p>(9) After modification, press Ctrl+x, and Y key to save modified buffer, then press Enter.</p><img loading="lazy" height="56" width="723" class="common_img" src="'+L+'"><ul><li><strong>PuppyPi Network Configuration</strong></li></ul><p>(1) Get access to Raspberry Pi desktop via VNC.</p><p>(2) Click <img loading="lazy" height="40" width="46" src="'+x+'"> or use shortcut <strong>&quot;Ctrl+Alt+T&quot;</strong> to open terminal</p><p>(3) Enter command and press Enter to change network configuration.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/hosts</span></span></code></pre></div><p>(4) Find the code marked in the below figure, then enter the IP of virtual machine which can be obtained in step 1.2. After that, press <strong>&quot;Esc&quot;</strong> key, enter <strong>&quot;:wq&quot;</strong> and press Enter key to save and exit.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:wq</span></span></code></pre></div><img loading="lazy" height="173" width="859" class="common_img" src="'+S+'"><p>(5) Run the command to update the configuration.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .bashrc</span></span></code></pre></div><h3 id="_16-3-2-configure-navigation" tabindex="-1">16.3.2 Configure Navigation <a class="header-anchor" href="#_16-3-2-configure-navigation" aria-label="Permalink to &quot;16.3.2 Configure Navigation&quot;">​</a></h3><p>(1) Connect to PuppyPi system. Then open the terminal <img loading="lazy" height="74" width="81" src="'+e+'" style="width:70px;">.</p><p>(2) Input command and press Enter to open navigation service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puppy_navigation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> navigation.launch</span></span></code></pre></div><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>By default, the map selected here is map1.</p></section><p>When you receive the following messages, PuppyPi navigation service is enabled successfully.</p><img loading="lazy" height="601" width="959" class="common_img" src="'+j+'"><p>(3) Open virtual machine, then input command and press Enter to open the model to check node.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosparam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /puppy_control/joint_state_pub_topic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><p>(4) Open a new command line terminal, then input command and press Enter to open model viewing software.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puppy_description</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rviz_with_urdf.launch</span></span></code></pre></div><img loading="lazy" height="881" width="1265" class="common_img" src="'+N+'"><p>(5) Click <strong>&quot;File-&gt;Open Config&quot;</strong>.</p><img loading="lazy" height="327" width="1000" class="common_img" src="'+R+'"><p>As shown in the image below, navigate to the corresponding path, select <strong>&quot;navigation.rviz&quot;,</strong> and then click <strong>&quot;Open&quot;</strong>.</p><img loading="lazy" height="784" width="1000" class="common_img" src="'+B+'"><img loading="lazy" height="774" width="1259" class="common_img" src="'+O+'"><h3 id="_16-3-3-start-navigation" tabindex="-1">16.3.3 Start Navigation <a class="header-anchor" href="#_16-3-3-start-navigation" aria-label="Permalink to &quot;16.3.3 Start Navigation&quot;">​</a></h3><p>You can issue commands to the robot dog based on the content highlighted in the red box in the image below. When navigating, we need to use the first tool to set the initial position of the robot dog. The second tool can be used to set the target point of the robot dog, while the third tool allows setting multiple target points. The robot dog will automatically set its route based on the map, avoiding obstacles to reach the target point.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If you need to interrupt the navigation, simply use the second tool to set a target point at the current location of the robot dog. If you pick up the robot dog or its position is altered by external forces, you will need to reset its position manually.</p></section><img loading="lazy" height="255" width="519" src="'+D+'" class="common_img"><p>(1) In the software menu bar, <strong>&quot;2D Pose Estimate&quot;</strong> is used to set the initial position of the PuppyPi robot dog.</p><img loading="lazy" height="34" width="997" class="common_img" src="'+G+'"><img loading="lazy" height="685" width="1268" class="common_img" src="'+E+'"><p>(2) <strong>&quot;2D Nav Goal&quot;</strong> is used to set a single target point for the robot. Click the icon and select a location on the map as the target point. Press the left mouse button at that point, then drag the mouse to select both the destination and orientation for the robot. After selection, the robot will automatically generate a route and move to the target point.</p><img loading="lazy" height="38" width="995" class="common_img" src="'+W+'"><img loading="lazy" height="678" width="1267" class="common_img" src="'+Y+'"><p>Once the target point is set, two lines will be generated: a red line and a green line. The red line represents the straight-line distance from the robot dog to the target, while the green line represents the route planned by the robot dog itself.</p><img loading="lazy" height="780" width="1255" class="common_img" src="'+Z+'"><h2 id="_16-4-app-navigation" tabindex="-1">16.4 App Navigation <a class="header-anchor" href="#_16-4-app-navigation" aria-label="Permalink to &quot;16.4 App Navigation&quot;">​</a></h2><h3 id="_16-4-1-preparation" tabindex="-1">16.4.1 Preparation <a class="header-anchor" href="#_16-4-1-preparation" aria-label="Permalink to &quot;16.4.1 Preparation&quot;">​</a></h3><p>Via the app, you can control PuppyPi&#39;s movement, view its mapping process and set the target point.</p><p>(1) <strong>&quot;Make A APP&quot;</strong> app is used for mapping and <strong>&quot;Map Nav&quot;</strong> app is used for navigation.</p><p>(2) These two apps only support Android system, and the installation pack is stored in the same folder.</p><p id="anchor_16_4_2"></p><h3 id="_16-4-2-navigation" tabindex="-1">16.4.2 Navigation <a class="header-anchor" href="#_16-4-2-navigation" aria-label="Permalink to &quot;16.4.2 Navigation&quot;">​</a></h3><ul><li><strong>Enable App Navigation Service</strong></li></ul><p>(1) Start PuppyPi, then access Raspberry Pi desktop via VNC.</p><p>(2) Click-on <img loading="lazy" height="74" width="81" src="'+e+'" style="width:70px;"> at upper left corner to open the Terminator terminal.</p><p>(3) Run the command and press Enter to enable app navigation service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/ubuntu/puppypi/src/puppy_navigation/scripts/navigation_app.sh</span></span></code></pre></div><ul><li><strong>App Navigation</strong></li></ul><p>(1) Turn on PuppyPi, then connect it to the remote control software VNC.</p><p>(2) Enable app service according to the instructions in &quot;<a href="#anchor_16_4_2"><strong>16.4.2 Navigation -&gt; Enable App Navigation Service</strong></a>&quot;.</p><p>(3) Move to <strong>&quot;settings&quot;</strong>, and connect to the Wi-Fi generated by the robot.</p><img loading="lazy" height="1122" width="1220" class="common_img" src="'+V+'" style="width:400px;"><p>(4) Open the app <strong>&quot;Map Nav&quot;</strong>, and input &quot;<strong><a href="http://192.168.149.1:11311" target="_blank" rel="noreferrer">http://192.168.149.1:11311</a></strong>&quot; in the filed <strong>&quot;Master URI&quot;</strong>. Then click <strong>&quot;CONNECT&quot;</strong> button.</p><img loading="lazy" height="860" width="1080" class="common_img" src="'+H+'" style="width:400px;"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The &quot;<strong>CHOOSE A MAP</strong>&quot; has no practical function. The map will be updated automatically.</p></section><p>The app interface is divided into 3 parts:</p><p><strong>① Green area:</strong> display the map</p><p><strong>② Red frame:</strong> control robot&#39;s movement</p><p><strong>③ Blue frame:</strong> the options <strong>&quot;Set Pose&quot;</strong> and <strong>&quot;Set Goal&quot;</strong> are used in conjunction with the green square. Set the initial position and the target position</p><img loading="lazy" height="636" width="1265" class="common_img" src="'+U+'"><p>(5) Select <strong>&quot;Set Pose&quot;</strong>. Then press one point on the map to set it as the initial position for the robot.</p><p>(6) To calibrate robot&#39;s position, drag the arrow at upper right corner to control robot to go forward, downward, and turn left, right.</p><p>(7) Select <strong>&quot;Set Goal&quot;</strong> and press one point on the map to set it as the target point.</p><p>(8) After the initial position and the target point are set, the robot will generate the path automatically, then move from the initial position to the target point based on this path. During PuppyPi is moving, its speed will be displayed in red area.</p>',181)])])}const nt=a(J,[["render",Q]]);export{ot as __pageData,nt as default};
